import json
with open('/app/resources/treasury_bulletin_2003_03.json', 'r') as f:
    data = json.load(f)

elements = data['document']['elements']
# Find all table types and look at their content
for i, elem in enumerate(elements):
    if elem.get('type') == 'table':
        content = elem.get('content')
        if content:
            print(f'Index {i}: keys={list(content.keys())}')
            if isinstance(content, dict) and 'data' in content:
                rows = content.get('data', [])
                if rows and len(rows) > 0:
                    first_row = rows[0]
                    print(f'  First row: {first_row[:5]}...')
        if i > 30:
            break
